#!/usr/bin/env python3
"""Verify the final V3 research-output manifest and all generated bytes."""

from __future__ import annotations

import argparse
import json
from pathlib import Path
from typing import Any

from scripts.research.audits.record_pretraining_scientific_gate import file_sha256

from artifacts.atomic import write_json_atomic

REQUIRED_OUTPUTS = {
    "CONSOLIDATED_RESEARCH_RESULTS.md",
    "KNOWN_LIMITATIONS.md",
    "THESIS_FIGURE_TABLE_INDEX.md",
    "FINAL_READINESS_REPORT.md",
}


def verify_manifest(path: Path, *, expected_source_commit: str) -> dict[str, Any]:
    value = json.loads(path.read_text(encoding="utf-8"))
    if not isinstance(value, dict) or value.get("schema_version") != "v3-final-research-outputs-v1":
        raise ValueError("invalid final V3 output manifest")
    outputs = value.get("outputs")
    if not isinstance(outputs, dict):
        raise ValueError("final output manifest has no outputs mapping")
    failures = []
    if value.get("source_commit") != expected_source_commit:
        failures.append("final output source_commit differs from expected source")
    for required in sorted(REQUIRED_OUTPUTS):
        if required not in outputs:
            failures.append(f"missing required output: {required}")
    for name, record in outputs.items():
        if not isinstance(record, dict):
            failures.append(f"malformed output record: {name}")
            continue
        output_path = Path(str(record.get("path", "")))
        if output_path.name != name or output_path.parent.resolve() != path.parent.resolve():
            failures.append(f"output path is outside the manifest directory or misnamed: {name}")
        if not output_path.is_file():
            failures.append(f"output file missing: {output_path}")
        elif file_sha256(output_path) != record.get("sha256"):
            failures.append(f"output hash mismatch: {output_path}")
    for table_id in (
        "survival",
        "model_baseline",
        "cost_execution",
        "action_funnel",
        "feature_causality",
    ):
        tables = value.get("tables")
        if not isinstance(tables, dict) or table_id not in tables or tables[table_id] is None:
            failures.append(f"required table missing: {table_id}")
            continue
        table = tables[table_id]
        if not isinstance(table, dict):
            failures.append(f"malformed required table: {table_id}")
            continue
        _verify_source_artifacts(table.get("source_artifacts"), f"table {table_id}", failures)
    figures = value.get("figures")
    if not isinstance(figures, list):
        failures.append("figure registry is missing or malformed")
    else:
        for index, figure in enumerate(figures):
            if not isinstance(figure, dict):
                failures.append(f"malformed figure record: {index}")
                continue
            figure_path = Path(str(figure.get("path", "")))
            if not figure_path.is_file():
                failures.append(f"figure file missing: {figure_path}")
            elif file_sha256(figure_path) != figure.get("sha256"):
                failures.append(f"figure hash mismatch: {figure_path}")
            _verify_source_artifacts(
                figure.get("source_artifacts"), f"figure {figure.get('figure_id', index)}", failures
            )
    limitations = value.get("limitations")
    if not isinstance(limitations, dict) or not limitations:
        failures.append("final limitations registry is missing")
    return {
        "schema_version": "v3-final-research-output-verification-v1",
        "status": "pass" if not failures else "fail",
        "manifest": str(path.resolve()),
        "manifest_sha256": file_sha256(path),
        "failures": failures,
    }


def _verify_source_artifacts(rows: Any, label: str, failures: list[str]) -> None:
    if not isinstance(rows, list) or not rows:
        failures.append(f"{label} has no source artifacts")
        return
    for row in rows:
        if not isinstance(row, dict):
            failures.append(f"{label} has malformed source artifact")
            continue
        source_path = Path(str(row.get("path", "")))
        if not source_path.is_file():
            failures.append(f"{label} source artifact missing: {source_path}")
        elif file_sha256(source_path) != row.get("sha256"):
            failures.append(f"{label} source artifact hash mismatch: {source_path}")


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--manifest", type=Path, required=True)
    parser.add_argument("--source-commit", required=True)
    parser.add_argument("--output", type=Path, required=True)
    args = parser.parse_args()
    report = verify_manifest(
        args.manifest.expanduser().resolve(), expected_source_commit=args.source_commit
    )
    args.output.parent.mkdir(parents=True, exist_ok=True)
    write_json_atomic(args.output, report)
    print(json.dumps(report, indent=2, sort_keys=True))
    return 0 if report["status"] == "pass" else 1


if __name__ == "__main__":
    raise SystemExit(main())
